#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <numeric>
#include <stdexcept>
#include <utility>
#include <vector>

using i64 = std::int64_t;

static std::vector<int> smallest_prime_factors(int limit) {
    std::vector<int> spf(limit + 1);
    std::iota(spf.begin(), spf.end(), 0);
    if (limit >= 1) spf[1] = 1;
    for (int p = 2; static_cast<i64>(p) * p <= limit; ++p) {
        if (spf[p] != p) continue;
        for (int multiple = p * p; multiple <= limit; multiple += p) {
            if (spf[multiple] == multiple) spf[multiple] = p;
        }
    }
    return spf;
}

static std::vector<std::pair<int, int>> factorize(int n, const std::vector<int>& spf) {
    std::vector<std::pair<int, int>> factors;
    while (n > 1) {
        const int prime = spf[n];
        int exponent = 0;
        while (n % prime == 0) {
            n /= prime;
            ++exponent;
        }
        factors.emplace_back(prime, exponent);
    }
    return factors;
}

static i64 ipow(i64 base, int exponent) {
    i64 result = 1;
    while (exponent-- > 0) result *= base;
    return result;
}

static i64 carmichael_lambda(const std::vector<std::pair<int, int>>& factors) {
    i64 result = 1;
    for (const auto& [prime, exponent] : factors) {
        const i64 component = prime == 2 && exponent >= 3
            ? ipow(2, exponent - 2)
            : (prime - 1) * ipow(prime, exponent - 1);
        result = std::lcm(result, component);
    }
    return result;
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: theox_integer_arithmetic_core LIMIT\n";
        return 2;
    }
    const int limit = std::atoi(argv[1]);
    if (limit < 1 || limit > 10000000) {
        std::cerr << "LIMIT must be between 1 and 10000000\n";
        return 2;
    }
    const auto spf = smallest_prime_factors(limit);
    std::cout << "n,smallest_prime_factor,largest_prime_factor,omega,big_omega,radical,divisor_count,divisor_sum,euler_phi,mobius,carmichael_lambda\n";
    for (int n = 1; n <= limit; ++n) {
        const auto factors = factorize(n, spf);
        i64 radical = 1;
        i64 divisor_count = 1;
        i64 divisor_sum = 1;
        i64 phi = 1;
        int big_omega = 0;
        bool squarefree = true;
        for (const auto& [prime, exponent] : factors) {
            radical *= prime;
            divisor_count *= exponent + 1;
            divisor_sum *= (ipow(prime, exponent + 1) - 1) / (prime - 1);
            phi *= (prime - 1) * ipow(prime, exponent - 1);
            big_omega += exponent;
            squarefree = squarefree && exponent == 1;
        }
        const int mobius = squarefree ? (factors.size() % 2 == 0 ? 1 : -1) : 0;
        std::cout << n << ','
                  << (factors.empty() ? 1 : factors.front().first) << ','
                  << (factors.empty() ? 1 : factors.back().first) << ','
                  << factors.size() << ',' << big_omega << ',' << radical << ','
                  << divisor_count << ',' << divisor_sum << ',' << phi << ','
                  << mobius << ',' << carmichael_lambda(factors) << '\n';
    }
    return 0;
}

